{
  "inputs": [
    {
      "type": "promptString",
      "id": "mcp-gate-pat-Folio",
      "description": "MCP Gate personal access token for Folio",
      "password": true
    },
    {
      "type": "promptString",
      "id": "mcp-gate-pat-Morph-yard",
      "description": "MCP Gate personal access token for Morph yard",
      "password": true
    },
    {
      "type": "promptString",
      "id": "mcp-gate-pat-Folio-2",
      "description": "MCP Gate personal access token for Folio",
      "password": true
    }
  ],
  "servers": {
    "Folio": {
      "type": "http",
      "url": "https://folio.example.com/mcp",
      "headers": {
        "Authorization": "Bearer ${input:mcp-gate-pat-Folio}"
      }
    },
    "Morph-yard": {
      "type": "http",
      "url": "http://127.0.0.1:5055/mcp",
      "headers": {
        "Authorization": "Bearer ${input:mcp-gate-pat-Morph-yard}"
      }
    },
    "Folio-2": {
      "type": "http",
      "url": "https://other.example.com/mcp",
      "headers": {
        "Authorization": "Bearer ${input:mcp-gate-pat-Folio-2}"
      }
    }
  }
}
